export const calculateCarbonMetrics = (userData) => {
  console.log("Received userData:", userData); // ✅ Log input data

  // Emission factors (adjust as needed)
  const emissionFactors = {
    electricity: 0.5, // kg CO₂ per kWh
    transportation: 0.2, // kg CO₂ per km
    waste: 0.1 // kg CO₂ per kg
  };

  // Calculate carbon footprint
  const footprint =
    (userData.electricity || 0) * emissionFactors.electricity +
    (userData.vehicleMiles || 0) * emissionFactors.transportation + // ✅ Fixed
    (userData.airTravel || 0) * emissionFactors.transportation + // ✅ Fixed
    (userData.wasteProduced || 0) * emissionFactors.waste; // ✅ Fixed (match Firestore)

  console.log("Calculated footprint:", footprint); // ✅ Log footprint calculation

  // Calculate other metrics
  const credits = footprint * 0.1;
  const progress = (footprint / 1000) * 100;
  const rank = Math.floor(Math.random() * 100);

  // Convert to numbers to avoid Firestore storing as string
  const result = {
    totalCarbon: parseFloat(footprint.toFixed(1)),
    credits: parseFloat(credits.toFixed(1)),
    progress: parseFloat(progress.toFixed(1)),
    rank
  };

  console.log("Final calculated metrics:", result); // ✅ Log final output

  return result;
};
